// Adapted from LocalMode UI (MIT) — apps/ui/registry/localmode/conversation/suggestions/suggestions.tsx

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"

export type PromptSuggestion = string | { label: string; value?: string; icon?: React.ReactNode }

export type PromptSuggestionsClassNames = {
  root?: string
  item?: string
}

export type PromptSuggestionsProps = {
  items: PromptSuggestion[]
  onSelect?: (value: string) => void
  layout?: "scroll" | "wrap"
  loading?: boolean
  label?: string
  className?: string
  classNames?: PromptSuggestionsClassNames
}

function normalize(item: PromptSuggestion) {
  if (typeof item === "string") return { label: item, value: item, icon: null }
  return { label: item.label, value: item.value ?? item.label, icon: item.icon ?? null }
}

export function PromptSuggestions({
  items,
  onSelect,
  layout = "wrap",
  loading = false,
  label = "Suggestions",
  className,
  classNames,
}: PromptSuggestionsProps) {
  const normalized = items.map(normalize)
  const [active, setActive] = React.useState(0)

  if (loading) {
    return (
      <div className={cn("flex gap-2", className)} aria-hidden="true">
        <Skeleton className="h-7 w-24 rounded-full" />
        <Skeleton className="h-7 w-28 rounded-full" />
        <Skeleton className="h-7 w-20 rounded-full" />
      </div>
    )
  }

  if (normalized.length === 0) return null

  return (
    <div
      role="list"
      aria-label={label}
      className={cn(
        layout === "scroll"
          ? "flex snap-x gap-2 overflow-x-auto [mask-image:linear-gradient(to_right,transparent,black_12px,black_calc(100%-12px),transparent)]"
          : "flex flex-wrap gap-2",
        className,
        classNames?.root,
      )}
      onKeyDown={(event) => {
        if (layout !== "scroll") return
        if (event.key !== "ArrowRight" && event.key !== "ArrowLeft") return
        event.preventDefault()
        const delta = event.key === "ArrowRight" ? 1 : -1
        const next = (active + delta + normalized.length) % normalized.length
        setActive(next)
        document.getElementById(`suggestion-${next}`)?.focus()
      }}
    >
      {normalized.map((item, index) => (
        <div role="listitem" key={`${item.value}-${index}`} className="snap-start">
          <Button
            id={layout === "scroll" ? `suggestion-${index}` : undefined}
            type="button"
            variant="outline"
            size="sm"
            tabIndex={layout === "scroll" ? (index === active ? 0 : -1) : 0}
            className={cn("max-w-[240px] rounded-full", classNames?.item)}
            onClick={() => onSelect?.(item.value)}
            onFocus={() => setActive(index)}
          >
            {item.icon}
            <span className="truncate">{item.label}</span>
          </Button>
        </div>
      ))}
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatDeskDate, isOverdueDate, type DeskOption } from "@/lib/inbox"
import type { FieldDef, MultiRecord } from "@/lib/multi-view"
import { PriorityBadge, type PriorityLevel } from "@/components/ui/priority-badge"
import { RecordProperties } from "@/components/ui/record-properties"
import { TagInput } from "@/components/ui/tag-input"

const BADGE_LEVEL: Record<string, PriorityLevel | null> = {
  low: "low",
  medium: "medium",
  high: "high",
  critical: "critical",
  urgent: "critical",
  none: null,
}

export type TicketSla = {
  text: string
  overdue?: boolean
}

export type TicketPropertiesClassNames = {
  root?: string
  row?: string
  label?: string
  value?: string
}

export type TicketPropertiesProps = {
  id?: string
  title?: string
  locale?: string
  /** Calendar day used to decide if the due date is overdue. */
  today: string
  status?: string
  statusOptions?: readonly DeskOption[]
  onStatusChange?: (value: string) => void
  statusLabel?: string
  priority?: string
  priorityOptions?: readonly DeskOption[]
  onPriorityChange?: (value: string) => void
  priorityLabel?: string
  type?: string
  typeOptions?: readonly DeskOption[]
  onTypeChange?: (value: string) => void
  typeLabel?: string
  assignee?: string
  assigneeOptions?: readonly DeskOption[]
  onAssigneeChange?: (value: string) => void
  assigneeLabel?: string
  due?: string
  onDueChange?: (value: string) => void
  dueLabel?: string
  overdueLabel?: string
  channel?: string
  created?: string
  updated?: string
  channelLabel?: string
  createdLabel?: string
  updatedLabel?: string
  metaLabel?: string
  sla?: TicketSla
  slaLabel?: string
  tags?: readonly string[]
  onTagsChange?: (tags: string[]) => void
  tagsLabel?: string
  className?: string
  classNames?: TicketPropertiesClassNames
}

function SelectRow({
  label,
  value,
  options,
  onChange,
  classNames,
  extra,
}: {
  label: string
  value?: string
  options: readonly DeskOption[]
  onChange?: (value: string) => void
  classNames?: TicketPropertiesClassNames
  extra?: React.ReactNode
}) {
  return (
    <label className={cn("grid gap-1 text-sm", classNames?.row)}>
      <span className={cn("text-xs text-muted-foreground", classNames?.label)}>{label}</span>
      <span className="flex min-w-0 items-center gap-2">
        <select
          aria-label={label}
          value={value ?? ""}
          disabled={!onChange}
          onChange={(event) => onChange?.(event.target.value)}
          className="h-8 min-w-0 flex-1 rounded-md border border-input bg-background px-2 text-sm text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none disabled:opacity-70"
        >
          {options.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
        {extra}
      </span>
    </label>
  )
}

export function TicketProperties({
  id = "ticket",
  title = "Properties",
  locale,
  today,
  status,
  statusOptions,
  onStatusChange,
  statusLabel = "Status",
  priority,
  priorityOptions,
  onPriorityChange,
  priorityLabel = "Priority",
  type,
  typeOptions,
  onTypeChange,
  typeLabel = "Type",
  assignee,
  assigneeOptions,
  onAssigneeChange,
  assigneeLabel = "Assignee",
  due,
  onDueChange,
  dueLabel = "Due",
  overdueLabel = "Overdue",
  channel,
  created,
  updated,
  channelLabel = "Channel",
  createdLabel = "Created",
  updatedLabel = "Updated",
  metaLabel = "Record",
  sla,
  slaLabel = "SLA",
  tags,
  onTagsChange,
  tagsLabel = "Tags",
  className,
  classNames,
}: TicketPropertiesProps) {
  const overdue = isOverdueDate(due, today)
  const badge = priority ? BADGE_LEVEL[priority] : undefined
  const metaFields: FieldDef[] = []
  const record: MultiRecord = { id }
  if (channel) {
    metaFields.push({ id: "channel", label: channelLabel, type: "text", icon: "link", readOnly: true, section: metaLabel })
    record.channel = channel
  }
  if (created) {
    metaFields.push({ id: "created", label: createdLabel, type: "text", icon: "calendar", readOnly: true, section: metaLabel })
    record.created = created
  }
  if (updated) {
    metaFields.push({ id: "updated", label: updatedLabel, type: "text", icon: "calendar", readOnly: true, section: metaLabel })
    record.updated = updated
  }

  return (
    <section data-slot="ticket-properties" aria-label={title} className={cn("flex min-w-0 flex-col gap-4 p-3", className, classNames?.root)}>
      <h2 className="text-sm font-semibold">{title}</h2>
      {statusOptions?.length ? (
        <SelectRow label={statusLabel} value={status} options={statusOptions} onChange={onStatusChange} classNames={classNames} />
      ) : null}
      {priorityOptions?.length ? (
        <SelectRow
          label={priorityLabel}
          value={priority}
          options={priorityOptions}
          onChange={onPriorityChange}
          classNames={classNames}
          extra={badge ? <PriorityBadge level={badge} label={priorityOptions.find((option) => option.value === priority)?.label} /> : null}
        />
      ) : null}
      {typeOptions?.length ? (
        <SelectRow label={typeLabel} value={type} options={typeOptions} onChange={onTypeChange} classNames={classNames} />
      ) : null}
      {assigneeOptions?.length ? (
        <SelectRow label={assigneeLabel} value={assignee} options={assigneeOptions} onChange={onAssigneeChange} classNames={classNames} />
      ) : null}
      {due !== undefined || onDueChange ? (
        <label className={cn("grid gap-1 text-sm", classNames?.row)}>
          <span className={cn("text-xs text-muted-foreground", classNames?.label)}>{dueLabel}</span>
          <input
            type="date"
            aria-label={dueLabel}
            value={due ?? ""}
            readOnly={!onDueChange}
            onChange={(event) => onDueChange?.(event.target.value)}
            className="h-8 rounded-md border border-input bg-background px-2 text-sm text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
          />
          {due ? (
            <span
              data-slot="ticket-due"
              data-overdue={overdue ? "true" : "false"}
              className={cn("text-xs tabular-nums", overdue ? "font-medium text-destructive" : "text-muted-foreground", classNames?.value)}
            >
              {formatDeskDate(due, locale)}
              {overdue ? ` · ${overdueLabel}` : ""}
            </span>
          ) : null}
        </label>
      ) : null}
      {metaFields.length ? <RecordProperties record={record} fields={metaFields} locale={locale} /> : null}
      {sla ? (
        <div className={cn("grid gap-1 text-sm", classNames?.row)} data-slot="ticket-sla" data-overdue={sla.overdue ? "true" : "false"}>
          <span className={cn("text-xs text-muted-foreground", classNames?.label)}>{slaLabel}</span>
          <span className={cn("text-sm wrap-anywhere", sla.overdue ? "font-medium text-destructive" : "text-foreground", classNames?.value)}>
            {sla.text}
          </span>
        </div>
      ) : null}
      {tags ? (
        <TagInput label={tagsLabel} value={[...tags]} onValueChange={onTagsChange} />
      ) : null}
    </section>
  )
}

