/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { cn } from "@/lib/utils"

export const PRIORITY_LEVELS = ["low", "medium", "high", "critical"] as const

export type PriorityLevel = (typeof PRIORITY_LEVELS)[number]

export type PriorityBadgeClassNames = {
  root?: string
  glyph?: string
  label?: string
}

export type PriorityBadgeProps = {
  level: PriorityLevel
  label?: string
  variant?: "chip" | "glyph" | "pill"
  /** Pill only. Soft keeps a wash. Solid fills high and critical. */
  appearance?: "soft" | "solid"
  className?: string
  classNames?: PriorityBadgeClassNames
}

const DEFAULT_LABEL: Record<PriorityLevel, string> = {
  low: "Low",
  medium: "Medium",
  high: "High",
  critical: "Critical",
}

export function priorityRank(level: PriorityLevel): number {
  return PRIORITY_LEVELS.indexOf(level) + 1
}

export function comparePriority(a: PriorityLevel, b: PriorityLevel): number {
  return priorityRank(a) - priorityRank(b)
}

function SignalGlyph({ filled, className }: { filled: number; className?: string }) {
  const heights = [4, 7, 10, 13]
  return (
    <svg viewBox="0 0 16 14" className={cn("h-3.5 w-4", className)} aria-hidden>
      {heights.map((height, index) => (
        <rect
          key={height}
          x={index * 4}
          y={14 - height}
          width="2.5"
          height={height}
          rx="0.5"
          className={index < filled ? "fill-current" : "fill-current opacity-30"}
        />
      ))}
    </svg>
  )
}

export function PriorityBadge({
  level,
  label,
  variant = "chip",
  appearance,
  className,
  classNames,
}: PriorityBadgeProps) {
  const text = label ?? DEFAULT_LABEL[level]
  const critical = level === "critical"
  if (variant === "pill") {
    const solid = appearance === "solid" || (appearance !== "soft" && (level === "high" || level === "critical"))
    return (
      <span
        data-slot="priority-badge"
        data-level={level}
        data-variant="pill"
        className={cn(
          "inline-flex h-6 max-w-full items-center rounded-full px-2 text-xs font-medium",
          solid && (level === "high" || level === "critical") && "bg-destructive text-background",
          solid && level !== "high" && level !== "critical" && "bg-foreground text-background",
          !solid && (level === "critical" || level === "high") && "bg-destructive/10 text-destructive",
          !solid && level === "medium" && "bg-chart-4/15 text-foreground",
          !solid && level === "low" && "bg-muted text-foreground",
          className,
          classNames?.root,
        )}
      >
        <span className={cn("truncate", classNames?.label)}>{text}</span>
      </span>
    )
  }
  if (variant === "glyph") {
    return (
      <span className={cn("inline-flex text-foreground", critical && "text-destructive", className, classNames?.root)} aria-label={text}>
        <SignalGlyph filled={priorityRank(level)} className={classNames?.glyph} />
      </span>
    )
  }
  return (
    <span
      data-slot="priority-badge"
      data-level={level}
      className={cn(
        "inline-flex h-6 max-w-full items-center gap-1 rounded-full px-2 text-xs font-medium",
        critical ? "bg-destructive/10 text-destructive" : "bg-muted text-foreground",
        className,
        classNames?.root,
      )}
    >
      <SignalGlyph filled={priorityRank(level)} className={classNames?.glyph} />
      <span className={cn("truncate", classNames?.label)}>{text}</span>
    </span>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  asPerson,
  isEmptyValue,
  parseDateOnly,
  type FieldDef,
  type MultiRecord,
} from "@/lib/multi-view"
import { FieldDisplay, FieldIcon } from "@/components/ui/multi-view-fields"

export type RecordPropertiesProps = {
  record: MultiRecord
  fields: readonly FieldDef[]
  locale?: string
  onChange?: (id: string, patch: Record<string, unknown>) => Promise<void> | void
  className?: string
  sectionClassName?: string
  rowClassName?: string
  labelClassName?: string
  valueClassName?: string
}

export function RecordProperties({
  record,
  fields,
  locale,
  onChange,
  className,
  sectionClassName,
  rowClassName,
  labelClassName,
  valueClassName,
}: RecordPropertiesProps) {
  const sections = React.useMemo(() => {
    const map = new Map<string, FieldDef[]>()
    for (const field of fields) {
      const name = field.section ?? "Details"
      const list = map.get(name)
      if (list) list.push(field)
      else map.set(name, [field])
    }
    return [...map.entries()]
  }, [fields])

  return (
    <div className={cn("@container flex flex-col gap-5", className)}>
      {sections.map(([name, sectionFields]) => (
        <section key={name} className={sectionClassName}>
          <h3 className="mb-2 text-xs font-medium tracking-wide text-muted-foreground uppercase">{name}</h3>
          <div className="grid gap-1">
            {sectionFields.map((field) => (
              <PropertyRow
                key={field.id}
                record={record}
                field={field}
                locale={locale}
                onChange={onChange}
                className={rowClassName}
                labelClassName={labelClassName}
                valueClassName={valueClassName}
              />
            ))}
          </div>
        </section>
      ))}
    </div>
  )
}

function PropertyRow({
  record,
  field,
  locale,
  onChange,
  className,
  labelClassName,
  valueClassName,
}: {
  record: MultiRecord
  field: FieldDef
  locale?: string
  onChange?: (id: string, patch: Record<string, unknown>) => Promise<void> | void
  className?: string
  labelClassName?: string
  valueClassName?: string
}) {
  const [editing, setEditing] = React.useState(false)
  const [draft, setDraft] = React.useState("")
  const [pending, setPending] = React.useState<unknown>(undefined)
  const [hasPending, setHasPending] = React.useState(false)
  const value = hasPending ? pending : record[field.id]

  async function commit(next: unknown) {
    setPending(next)
    setHasPending(true)
    setEditing(false)
    try {
      await onChange?.(record.id, { [field.id]: next })
      setHasPending(false)
    } catch {
      setHasPending(false)
      setPending(undefined)
    }
  }

  function start() {
    if (field.readOnly || !onChange) return
    if (field.type === "text" || field.type === "url" || field.type === "number" || field.type === "currency" || field.type === "progress") {
      const current = record[field.id]
      setDraft(current == null ? "" : String(current))
      setEditing(true)
      return
    }
    if (field.type === "person" || field.type === "relation") {
      setDraft(asPerson(record[field.id])?.name ?? "")
      setEditing(true)
    }
  }

  function cancel() {
    setEditing(false)
  }

  async function commitDraft() {
    if (field.type === "number" || field.type === "currency" || field.type === "progress") {
      if (draft.trim() === "") {
        await commit(null)
        return
      }
      const n = Number(draft)
      if (!Number.isFinite(n)) return
      await commit(n)
      return
    }
    if (field.type === "person" || field.type === "relation") {
      await commit(draft.trim() ? { name: draft.trim() } : null)
      return
    }
    await commit(draft)
  }

  return (
    <div className={cn("grid min-w-0 grid-cols-1 items-start gap-1 py-1 @min-[22rem]:grid-cols-[minmax(0,9rem)_minmax(0,1fr)] @min-[22rem]:items-center @min-[22rem]:gap-2", className)}>
      <div className={cn("flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground", labelClassName)}>
        <FieldIcon name={field.icon} className="size-3.5 shrink-0" />
        <span className="truncate">{field.label}</span>
      </div>
      <div className={cn("min-w-0 text-sm break-words", valueClassName)}>
        {field.readOnly || !onChange ? (
          <FieldDisplay field={field} value={value} locale={locale} />
        ) : field.type === "boolean" ? (
          <Checkbox
            aria-label={field.label}
            checked={value === true}
            onCheckedChange={(checked) => void commit(checked === true)}
          />
        ) : field.type === "select" || field.type === "status" ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button type="button" className="rounded-sm text-left focus-visible:ring-2 focus-visible:ring-ring">
                <FieldDisplay field={field} value={value} locale={locale} />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start">
              {(field.options ?? []).map((option) => (
                <DropdownMenuItem key={option.value} onSelect={() => void commit(option.value)}>
                  {option.label}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        ) : field.type === "date" ? (
          <DateEditor field={field} value={value} locale={locale} onCommit={(next) => void commit(next)} />
        ) : editing ? (
          <Input
            autoFocus
            aria-label={field.label}
            value={draft}
            inputMode={field.type === "number" || field.type === "currency" || field.type === "progress" ? "decimal" : undefined}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault()
                void commitDraft()
              }
              if (event.key === "Escape") {
                event.preventDefault()
                cancel()
              }
            }}
          />
        ) : (
          <button
            type="button"
            className="max-w-full truncate rounded-sm text-left focus-visible:ring-2 focus-visible:ring-ring"
            onClick={start}
          >
            {isEmptyValue(value) ? <span className="text-muted-foreground">Empty</span> : <FieldDisplay field={field} value={value} locale={locale} />}
          </button>
        )}
      </div>
    </div>
  )
}

function DateEditor({
  field,
  value,
  locale,
  onCommit,
}: {
  field: FieldDef
  value: unknown
  locale?: string
  onCommit: (value: string | null) => void
}) {
  const iso = typeof value === "string" && parseDateOnly(value) ? value : ""
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button type="button" className="rounded-sm text-left focus-visible:ring-2 focus-visible:ring-ring" aria-label={field.label}>
          <FieldDisplay field={field} value={value} locale={locale} />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto">
        <Input
          type="date"
          aria-label={field.label}
          defaultValue={iso}
          onChange={(event) => onCommit(event.target.value || null)}
          onKeyDown={(event) => {
            if (event.key === "Escape") event.currentTarget.blur()
          }}
        />
      </PopoverContent>
    </Popover>
  )
}

export function propertySections(fields: readonly FieldDef[]): string[] {
  return [...new Set(fields.map((field) => field.section ?? "Details"))]
}

"use client"

import * as React from "react"
import {
  Building2,
  Calendar,
  Check,
  DollarSign,
  Flag,
  CircleDot,
  Hash,
  ImageIcon,
  Link,
  ListChecks,
  Tag,
  Type,
  UserRound,
} from "lucide-react"

import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import {
  asPerson,
  formatFieldValue,
  isEmptyValue,
  optionTone,
  type ChartTone,
  type FieldDef,
  type FieldIconName,
  type MultiRecord,
} from "@/lib/multi-view"

const ICONS: Record<FieldIconName, React.ComponentType<{ className?: string }>> = {
  text: Type,
  hash: Hash,
  currency: DollarSign,
  calendar: Calendar,
  user: UserRound,
  link: Link,
  image: ImageIcon,
  check: Check,
  status: ListChecks,
  flag: Flag,
  building: Building2,
  progress: CircleDot,
  tag: Tag,
}

const TONE_CLASS: Record<ChartTone, string> = {
  1: "bg-chart-1",
  2: "bg-chart-2",
  3: "bg-chart-3",
  4: "bg-chart-4",
  5: "bg-chart-5",
}

export function toneClass(tone: ChartTone): string {
  return TONE_CLASS[tone]
}

export function FieldIcon({
  name,
  className,
}: {
  name?: FieldIconName
  className?: string
}) {
  if (!name) return null
  const Icon = ICONS[name]
  return <Icon className={className} aria-hidden />
}

export function initials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (!parts.length) return "?"
  if (parts.length === 1) return parts[0]!.slice(0, 2).toUpperCase()
  return `${parts[0]![0] ?? ""}${parts[1]![0] ?? ""}`.toUpperCase()
}

export function PersonFace({
  name,
  className,
}: {
  name: string
  className?: string
}) {
  return (
    <Avatar size="sm" className={className}>
      <AvatarFallback className="text-[10px]">{initials(name)}</AvatarFallback>
    </Avatar>
  )
}

export function StatusPill({
  field,
  value,
  className,
}: {
  field: FieldDef
  value: unknown
  className?: string
}) {
  if (isEmptyValue(value)) return <span className="text-muted-foreground">—</span>
  const text = formatFieldValue(value, field)
  const index = field.options?.findIndex((option) => option.value === String(value)) ?? 0
  const tone = optionTone(field, String(value), Math.max(0, index))
  return (
    <Badge variant="outline" className={cn("max-w-full", className)}>
      <span className={cn("size-1.5 rounded-full", toneClass(tone))} aria-hidden />
      <span className="truncate">{text}</span>
    </Badge>
  )
}

export function FieldDisplay({
  field,
  value,
  locale,
  className,
}: {
  field: FieldDef
  value: unknown
  locale?: string
  className?: string
}) {
  if (isEmptyValue(value)) {
    return <span className={cn("text-muted-foreground", className)}>—</span>
  }
  if (field.type === "status" || field.type === "select") {
    return <StatusPill field={field} value={value} className={className} />
  }
  if (field.type === "person" || field.type === "relation") {
    const person = asPerson(value)
    if (!person) return <span className="text-muted-foreground">—</span>
    return (
      <span className={cn("inline-flex min-w-0 items-center gap-1.5", className)}>
        <PersonFace name={person.name} />
        <span className="truncate">{person.name}</span>
      </span>
    )
  }
  if (field.type === "progress") {
    const n = typeof value === "number" ? value : Number(value)
    return (
      <span className={cn("inline-flex items-center gap-1.5", className)}>
        <ProgressRing value={Number.isFinite(n) ? n : 0} />
        <span>{formatFieldValue(value, field, locale)}</span>
      </span>
    )
  }
  const text = formatFieldValue(value, field, locale)
  if (field.type === "url" && typeof value === "string") {
    return (
      <a
        href={value}
        className={cn("truncate underline-offset-2 hover:underline", className)}
        dir="auto"
      >
        {text}
      </a>
    )
  }
  return (
    <span className={cn("truncate", className)} dir="auto">
      {text}
    </span>
  )
}

export function ProgressRing({ value, className }: { value: number; className?: string }) {
  const pct = Math.max(0, Math.min(100, value))
  return (
    <svg viewBox="0 0 16 16" className={cn("size-4 shrink-0", className)} aria-hidden>
      <circle cx="8" cy="8" r="6" fill="none" className="stroke-muted" strokeWidth="2" />
      <circle
        cx="8"
        cy="8"
        r="6"
        fill="none"
        className="stroke-primary"
        strokeWidth="2"
        strokeLinecap="round"
        strokeDasharray={`${pct} ${100 - pct}`}
        pathLength={100}
        transform="rotate(-90 8 8)"
      />
    </svg>
  )
}

export function usePrefersReducedMotion() {
  const [reduced, setReduced] = React.useState(false)
  React.useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)")
    const apply = () => setReduced(query.matches)
    apply()
    query.addEventListener("change", apply)
    return () => query.removeEventListener("change", apply)
  }, [])
  return reduced
}

export function useContainerWidth<T extends HTMLElement>() {
  const ref = React.useRef<T>(null)
  const [width, setWidth] = React.useState(0)
  React.useEffect(() => {
    const node = ref.current
    if (!node) return
    const measure = () => setWidth(node.clientWidth)
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(node)
    return () => observer.disconnect()
  }, [])
  return [ref, width] as const
}

export function displayFields(
  fields: readonly FieldDef[],
  ids: readonly string[] | undefined,
  skip: ReadonlySet<string>,
): FieldDef[] {
  const source = ids?.length
    ? ids.map((id) => fields.find((field) => field.id === id)).filter((field): field is FieldDef => Boolean(field))
    : fields
  return source.filter((field) => !skip.has(field.id))
}

export function recordValue(record: MultiRecord, field: FieldDef) {
  return record[field.id]
}

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { AnimatePresence, motion, useAnimate, useReducedMotion } from "motion/react"
import { X } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type TagInputClassNames = {
  root?: string
  label?: string
  control?: string
  tag?: string
  input?: string
  description?: string
}

export type TagInputProps = {
  label: string
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (value: string[]) => void
  placeholder?: string
  description?: string
  id?: string
  className?: string
  classNames?: TagInputClassNames
}

function MotionText({ text }: { text: string }) {
  const reduced = useReducedMotion()
  const words = text.split(" ")
  return (
    <>
      <span className="sr-only">{text}</span>
      <span className="relative block" aria-hidden="true">
        <AnimatePresence initial={false} mode="popLayout">
          {words.map((word, index) => (
            <motion.span
              key={`${index}:${word}`}
              className="inline-block whitespace-pre"
              initial={reduced ? { opacity: 0 } : { opacity: 0, y: "0.35em", filter: `blur(${motionPresets.blur.soft}px)` }}
              animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
              exit={
                reduced
                  ? { opacity: 0, transition: { duration: 0 } }
                  : {
                      opacity: 0,
                      y: "-0.35em",
                      filter: `blur(${motionPresets.blur.subtle}px)`,
                      transition: { duration: 0.14, ease: [...motionPresets.ease.standard] },
                    }
              }
              transition={
                reduced
                  ? { duration: motionPresets.duration.instant }
                  : { duration: motionPresets.duration.standard, ease: [...motionPresets.ease.enter] }
              }
            >
              {index < words.length - 1 ? `${word} ` : word}
            </motion.span>
          ))}
        </AnimatePresence>
      </span>
    </>
  )
}

function MessageRow({ id, text, className }: { id?: string; text: string; className?: string }) {
  const reduced = useReducedMotion()
  const copyRef = React.useRef<HTMLSpanElement>(null)
  const [height, setHeight] = React.useState<number | "auto">("auto")

  React.useEffect(() => {
    const node = copyRef.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(([entry]) => {
      setHeight(entry.borderBoxSize?.[0]?.blockSize ?? node.offsetHeight)
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [])

  return (
    <motion.span
      className="block overflow-hidden"
      initial={reduced ? false : { height: 0, opacity: 0 }}
      animate={{ height, opacity: 1 }}
      exit={{
        height: 0,
        opacity: 0,
        transition: reduced
          ? { duration: 0 }
          : { height: motionPresets.spring.smooth, opacity: { duration: motionPresets.duration.instant } },
      }}
      transition={
        reduced
          ? { duration: 0 }
          : { height: motionPresets.spring.smooth, opacity: { duration: motionPresets.duration.fast } }
      }
    >
      <motion.span
        ref={copyRef}
        id={id}
        className={cn("block pt-2 text-xs text-muted-foreground break-all", className)}
        initial={reduced ? false : { y: "0.35em", filter: `blur(${motionPresets.blur.soft}px)` }}
        animate={{ y: 0, filter: "blur(0px)" }}
        transition={{ duration: reduced ? 0 : motionPresets.duration.standard, ease: [...motionPresets.ease.enter] }}
      >
        <MotionText text={text} />
      </motion.span>
    </motion.span>
  )
}

function FieldMessage({ id, text, className }: { id?: string; text?: string; className?: string }) {
  return (
    <AnimatePresence initial={false}>
      {text ? <MessageRow key="message" id={id} text={text} className={className} /> : null}
    </AnimatePresence>
  )
}

export function TagInput({
  label,
  value,
  defaultValue = [],
  onValueChange,
  placeholder = "Add a tag",
  description,
  id,
  className,
  classNames,
}: TagInputProps) {
  const generatedId = React.useId()
  const inputId = id ?? generatedId
  const hintId = description ? `${inputId}-description` : undefined
  const [internal, setInternal] = React.useState(defaultValue)
  const [draft, setDraft] = React.useState("")
  const [picked, setPicked] = React.useState<string | null>(null)
  const [notice, setNotice] = React.useState("")
  const reduced = useReducedMotion()
  const [scope, animate] = useAnimate<HTMLDivElement>()
  const contentRef = React.useRef<HTMLDivElement>(null)
  const inputRef = React.useRef<HTMLInputElement>(null)
  const ringRef = React.useRef<HTMLSpanElement>(null)
  const ringAt = React.useRef("")
  const [height, setHeight] = React.useState<number | "auto">("auto")
  const tags = value ?? internal
  const active = picked !== null && tags.includes(picked) ? picked : null

  React.useEffect(() => {
    const node = contentRef.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => setHeight(node.offsetHeight))
    observer.observe(node)
    return () => observer.disconnect()
  }, [])

  React.useLayoutEffect(() => {
    const ring = ringRef.current
    const node = active === null ? null : contentRef.current?.querySelector<HTMLElement>(`[data-tag="${CSS.escape(active)}"]`)
    if (!ring) return
    if (!node) {
      if (ringAt.current) {
        animate(
          ring,
          reduced ? { opacity: 0 } : { opacity: 0, scale: 0.9 },
          { duration: reduced ? 0 : motionPresets.duration.instant, ease: [...motionPresets.ease.standard] },
        )
      }
      ringAt.current = ""
      return
    }
    const box = { x: node.offsetLeft, y: node.offsetTop, width: node.offsetWidth, height: node.offsetHeight }
    const at = Object.values(box).join(" ")
    if (at === ringAt.current) return
    if (!reduced && (ringAt.current || Number(getComputedStyle(ring).opacity) > 0.02)) {
      animate(ring, { ...box, opacity: 1, scale: 1 }, { ...motionPresets.spring.morph, opacity: { duration: motionPresets.duration.fast } })
    } else {
      animate(
        ring,
        { ...box, opacity: [0, 1], scale: [reduced ? 1 : 0.9, 1] },
        reduced
          ? { duration: 0, opacity: { duration: motionPresets.duration.instant } }
          : { duration: 0, opacity: { duration: motionPresets.duration.fast }, scale: motionPresets.spring.snappy },
      )
    }
    ringAt.current = at
  })

  function say(message: string) {
    setNotice((previous) => (previous === message ? `${message}\u00a0` : message))
  }

  function update(next: string[]) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function pick(tag: string | null) {
    setPicked(tag)
    if (tag !== null) say(`${tag} selected. Press Backspace to remove it.`)
  }

  function add() {
    const tag = draft.trim()
    if (!tag) return
    const existing = tags.find((item) => item.toLowerCase() === tag.toLowerCase())
    if (existing) {
      const node = scope.current?.querySelector(`[data-tag="${CSS.escape(existing)}"]`)
      if (node && !reduced) {
        animate(node, { scale: [1, 1.06, 1] }, { duration: 0.32, ease: [...motionPresets.ease.standard] })
      }
      say(`${existing} is already added`)
      return
    }
    update([...tags, tag])
    setDraft("")
    setPicked(null)
    say(`Added ${tag}`)
  }

  function remove(tag: string) {
    update(tags.filter((item) => item !== tag))
    setPicked(null)
    say(`Removed ${tag}`)
    inputRef.current?.focus()
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    const { key, currentTarget: input } = event
    const atStart = input.selectionStart === 0 && input.selectionEnd === 0
    const index = active === null ? tags.length : tags.indexOf(active)
    let handled = true
    if (key === "Enter" || key === ",") add()
    else if ((key === "Backspace" || key === "Delete") && active !== null) remove(active)
    else if (key === "Backspace" && atStart && tags.length) pick(tags[tags.length - 1])
    else if (key === "ArrowLeft" && (atStart || active !== null) && index > 0) pick(tags[index - 1])
    else if (key === "ArrowRight" && active !== null) pick(tags[index + 1] ?? null)
    else if (key === "Escape" && active !== null) pick(null)
    else handled = false
    if (handled) event.preventDefault()
  }

  function onTagPointer(event: React.MouseEvent<HTMLElement>, tag?: string) {
    if ((event.target as HTMLElement).closest("button")) return
    if (!tag) {
      event.preventDefault()
      return
    }
    pick(active === tag ? null : tag)
    inputRef.current?.focus()
  }

  const move = reduced ? { duration: 0 } : motionPresets.spring.morph

  return (
    <div data-slot="tag-input" className={cn("grid w-full min-w-0 max-w-full", className, classNames?.root)}>
      <Label htmlFor={inputId} data-slot="tag-input-label" className={cn("mb-2", classNames?.label)}>
        {label}
      </Label>
      <motion.div
        ref={scope}
        data-slot="tag-input-control"
        className={cn(
          "overflow-hidden rounded-lg border border-input bg-background shadow-sm transition-colors focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50 motion-reduce:transition-none",
          classNames?.control,
        )}
        initial={false}
        animate={{ height }}
        transition={reduced ? { duration: 0 } : motionPresets.spring.smooth}
      >
        <div
          ref={contentRef}
          className="relative flex min-h-9 cursor-text flex-wrap content-start items-center gap-1.5 p-[7px]"
          onMouseDown={(event) => {
            if (event.target !== event.currentTarget) return
            event.preventDefault()
            inputRef.current?.focus()
          }}
        >
          <span
            ref={ringRef}
            className="pointer-events-none absolute top-0 left-0 z-10 box-border rounded-full border border-primary bg-accent opacity-0"
            aria-hidden="true"
          />
          <AnimatePresence initial={false}>
            {!draft && !tags.length ? (
              <motion.span
                key="placeholder"
                className="pointer-events-none absolute inset-0 flex items-center overflow-hidden px-3 text-sm text-muted-foreground whitespace-nowrap"
                aria-hidden="true"
                initial={reduced ? { opacity: 0 } : { opacity: 0, y: "0.3em", filter: `blur(${motionPresets.blur.soft}px)` }}
                animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                exit={{ opacity: 0, transition: { duration: 0 } }}
                transition={reduced ? { duration: motionPresets.duration.instant } : { duration: 0.22, ease: [...motionPresets.ease.enter] }}
              >
                {placeholder}
              </motion.span>
            ) : null}
          </AnimatePresence>
          <AnimatePresence initial={false} mode="popLayout">
            {tags.map((tag) => (
              <motion.span
                layout={reduced ? false : "position"}
                className={cn(
                  "group relative inline-flex max-w-full min-w-0 items-center gap-0.5 rounded-full border border-border bg-muted py-0.5 pr-0.5 pl-2 text-sm text-foreground data-[picked]:[&_button]:text-foreground",
                  classNames?.tag,
                )}
                key={tag}
                data-tag={tag}
                data-slot="tag-input-tag"
                data-picked={tag === active || undefined}
                onMouseDown={(event) => onTagPointer(event)}
                onClick={(event) => onTagPointer(event, tag)}
                initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.9, filter: `blur(${motionPresets.blur.soft}px)` }}
                animate={{ opacity: 1, scale: 1, filter: "blur(0px)", transitionEnd: { filter: "none" } }}
                exit={
                  reduced
                    ? { opacity: 0, transition: { duration: 0 } }
                    : {
                        opacity: 0,
                        scale: 0.9,
                        filter: `blur(${motionPresets.blur.subtle}px)`,
                        transition: { duration: motionPresets.duration.instant, ease: [...motionPresets.ease.standard] },
                      }
                }
                transition={
                  reduced
                    ? { duration: motionPresets.duration.instant }
                    : {
                        ...motionPresets.spring.morph,
                        layout: move,
                        opacity: { duration: motionPresets.duration.fast, ease: [...motionPresets.ease.enter] },
                        filter: { duration: 0.22, ease: [...motionPresets.ease.enter] },
                      }
                }
              >
                <span className="relative z-20 min-w-0 break-all">{tag}</span>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-xs"
                  className="relative z-20 size-5 rounded-full text-muted-foreground hover:bg-background hover:text-foreground"
                  aria-label={`Remove ${tag}`}
                  onClick={() => remove(tag)}
                >
                  <X aria-hidden="true" />
                </Button>
              </motion.span>
            ))}
          </AnimatePresence>
          <motion.div layout={reduced ? false : "position"} transition={{ layout: move }} className="min-w-20 flex-1 basis-[100px]">
            <Input
              ref={inputRef}
              id={inputId}
              value={draft}
              onChange={(event) => {
                setDraft(event.currentTarget.value)
                setPicked(null)
              }}
              onKeyDown={onKeyDown}
              onBlur={() => {
                add()
                setPicked(null)
              }}
              placeholder={tags.length ? "" : placeholder}
              aria-describedby={hintId}
              data-slot="tag-input-input"
              className={cn(
                "h-7 min-h-7 border-0 bg-transparent px-1 shadow-none placeholder:text-transparent focus-visible:ring-0 dark:bg-transparent",
                classNames?.input,
              )}
            />
          </motion.div>
        </div>
      </motion.div>
      <span className="sr-only" aria-live="polite">
        {notice}
      </span>
      <FieldMessage id={hintId} text={description} className={classNames?.description} />
    </div>
  )
}

/**
 * Shared types for the desk pieces. No fetching, no theme.
 * Dates are calendar days (`YYYY-MM-DD`). The host owns locale and timezone.
 */

export const DESK_PRESENCES = ["online", "offline", "away"] as const

export type DeskPresence = (typeof DESK_PRESENCES)[number]

export type DeskMessage = {
  id: string
  author: string
  body: string
  /** Preformatted time. */
  time: string
  side: "incoming" | "outgoing"
  note?: boolean
  receipt?: "seen" | "unseen"
}

export type DeskOption = {
  value: string
  label: string
}

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/

export function foldInboxText(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
}

export function isCalendarDate(value: string | undefined): value is string {
  return Boolean(value && DATE_RE.test(value))
}

/** True when `due` is a calendar day before `today`. */
export function isOverdueDate(due: string | undefined, today: string): boolean {
  if (!isCalendarDate(due) || !isCalendarDate(today)) return false
  return due < today
}

export function formatDeskDate(iso: string, locale?: string): string {
  if (!isCalendarDate(iso)) return iso
  const [year, month, day] = iso.split("-").map(Number)
  return new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeZone: "UTC" }).format(
    new Date(Date.UTC(year, month - 1, day)),
  )
}

export function deskInitials(name: string): string {
  const letters = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
  return letters || "?"
}

