export type MultiRecord = { id: string } & Record<string, unknown>

export type PersonValue = { name: string; avatarUrl?: string | null }

export type DateRangeValue = { start: string; end: string }

export const FILTER_OPS = [
  "is",
  "isNot",
  "contains",
  "gt",
  "lt",
  "empty",
  "notEmpty",
  "before",
  "after",
